import random

secret = random.randint(1, 20)
print("Я загадал число от 1 до 20. Угадай!")

while True:
    try:
        guess = int(input("Твой вариант: "))
    except ValueError:
        print("Введи число!")
        continue

    if guess == secret:
        print("🎉 Ура, ты угадал!")
        break
    elif guess < secret:
        print("Загаданное число БОЛЬШЕ")
    else:
        print("Загаданное число МЕНЬШЕ")

import random
from ai import ask

JOKES = ["Шутка 1", "Шутка 2", "Шутка 3"]

while True:
    text = input("Ты: ").strip()
    if text == "/exit":
        print("Пока!")
        break
    elif text == "/help":
        print("Команды: /joke, /dice, /exit или просто задай вопрос!")
    elif text == "/joke":
        print(random.choice(JOKES))
    elif text == "/dice":
        print("Выпало:", random.randint(1, 6))
    else:
        print(ask(text, system="Ты весёлый бот-собеседник. Отвечай коротко."))
